import 'package:flutter/material.dart';
import '../../core/network/api_client.dart';

class VariationSetupPage extends StatefulWidget{
  const VariationSetupPage({super.key,required this.client,required this.productId});
  final ApiClient client;final int productId;
  @override State<VariationSetupPage> createState()=>_VariationSetupPageState();
}

class _VariationSetupPageState extends State<VariationSetupPage>{
  late Future<List<dynamic>> _attributes;
  Future<List<dynamic>>? _terms;
  int? _attributeId;
  final Set<int> _selected={};
  final price=TextEditingController(),quantity=TextEditingController(text:'0');
  bool manageStock=true,busy=false;String stockStatus='instock';
  @override void initState(){super.initState();_attributes=widget.client.attributes();}
  @override void dispose(){price.dispose();quantity.dispose();super.dispose();}
  void _choose(int? id){setState((){_attributeId=id;_selected.clear();_terms=id==null?null:widget.client.attributeTerms(id);});}
  Future<void> _submit()async{
    final amount=double.tryParse(price.text.trim());
    if(_attributeId==null||_selected.isEmpty||amount==null||amount<=0){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ویژگی، حداقل یک مقدار و قیمت اصلی معتبر الزامی است.')));return;}
    final confirm=await showDialog<bool>(context:context,builder:(context)=>AlertDialog(title:const Text('ساخت مدل‌های محصول'),content:Text('برای ${_selected.length} مقدار انتخاب‌شده مدل واقعی ووکامرس ساخته می‌شود. اگر محصول ساده باشد به محصول متغیر تبدیل خواهد شد.'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('انصراف')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('تأیید و ساخت'))]));
    if(confirm!=true)return;setState(()=>busy=true);
    try{final result=await widget.client.setupVariations(widget.productId,{'attribute_id':_attributeId,'term_ids':_selected.toList(),'regular_price':amount,'manage_stock':manageStock,'stock_quantity':int.tryParse(quantity.text.trim())??0,'stock_status':stockStatus});final created=(result['created'] as List? ?? const []).length,skipped=(result['skipped'] as List? ?? const []).length;if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$created مدل ساخته شد${skipped>0?'؛ $skipped مدل از قبل وجود داشت.':''}')));Navigator.pop(context,true);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('ساخت مدل‌ها انجام نشد: $e')));}finally{if(mounted)setState(()=>busy=false);}
  }
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('ساخت مدل‌های محصول')),body:Stack(children:[ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('۱. انتخاب ویژگی',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:12),FutureBuilder<List<dynamic>>(future:_attributes,builder:(context,snapshot){if(snapshot.connectionState!=ConnectionState.done)return const LinearProgressIndicator();if(snapshot.hasError)return Text('دریافت ویژگی‌ها انجام نشد: ${snapshot.error}');final items=snapshot.data??const [];if(items.isEmpty)return const Text('ابتدا از بخش کاتالوگ یک ویژگی مثل رنگ یا سایز بسازید.');return DropdownButtonFormField<int>(value:_attributeId,decoration:const InputDecoration(labelText:'ویژگی مدل'),items:items.map((raw){final a=Map<String,dynamic>.from(raw as Map);return DropdownMenuItem<int>(value:(a['id'] as num).toInt(),child:Text('${a['name']}'));}).toList(),onChanged:busy?null:_choose);} )]))),if(_terms!=null)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('۲. انتخاب رنگ یا مدل',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:12),FutureBuilder<List<dynamic>>(future:_terms,builder:(context,snapshot){if(snapshot.connectionState!=ConnectionState.done)return const LinearProgressIndicator();if(snapshot.hasError)return Text('دریافت مقادیر انجام نشد: ${snapshot.error}');final items=snapshot.data??const [];if(items.isEmpty)return const Text('برای این ویژگی هنوز مقداری ثبت نشده است.');return Wrap(spacing:8,runSpacing:8,children:items.map((raw){final term=Map<String,dynamic>.from(raw as Map),id=(term['id'] as num).toInt();return FilterChip(label:Text('${term['name']}'),selected:_selected.contains(id),onSelected:busy?null:(v)=>setState(()=>v?_selected.add(id):_selected.remove(id)));}).toList());})]))),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('۳. قیمت و موجودی اولیه',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:12),TextField(controller:price,enabled:!busy,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'قیمت اصلی هر مدل')),SwitchListTile(contentPadding:EdgeInsets.zero,value:manageStock,onChanged:busy?null:(v)=>setState(()=>manageStock=v),title:const Text('مدیریت موجودی جداگانه')),if(manageStock)TextField(controller:quantity,enabled:!busy,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'موجودی اولیه هر مدل')),DropdownButtonFormField<String>(value:stockStatus,decoration:const InputDecoration(labelText:'وضعیت موجودی'),items:const [DropdownMenuItem(value:'instock',child:Text('موجود')),DropdownMenuItem(value:'outofstock',child:Text('ناموجود')),DropdownMenuItem(value:'onbackorder',child:Text('پیش‌خرید'))],onChanged:busy?null:(v)=>setState(()=>stockStatus=v??'instock'))]))),SafeArea(child:SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:busy?null:_submit,icon:const Icon(Icons.account_tree_rounded),label:const Text('ساخت مدل‌های انتخاب‌شده'))))]),if(busy)const LinearProgressIndicator()]));
}
